const filas = $input.all().map((i) => i.json).filter((f) => f && f.start_utc);
const tz = 'America/Mexico_City';
function fecha(iso) { return new Intl.DateTimeFormat('es-MX', { timeZone: tz, dateStyle: 'full' }).format(new Date(iso)); }
function hora(iso) { return new Intl.DateTimeFormat('es-MX', { timeZone: tz, hour: '2-digit', minute: '2-digit', hour12: false }).format(new Date(iso)); }
if (filas.length === 0) {
  return [{ json: { ok: true, tiene_citas: false, citas: [], resumen: 'Este contacto no tiene ninguna cita registrada a futuro.' } }];
}
const citas = filas.map((f) => ({ evento_id: f.event_id, zoom_id: f.zoom_meeting_id ? String(f.zoom_meeting_id) : null, titulo: f.summary, dia: fecha(f.start_utc), de: hora(f.start_utc), a: hora(f.end_utc), inicio_utc: f.start_utc, fin_utc: f.end_utc, zoom: f.zoom_join_url || null, enlace: 'https://wa.geekstudio.dev/api/r/' + f.token }));
const resumen = citas.map((c) => c.titulo + ': ' + c.dia + ', de ' + c.de + ' a ' + c.a + ' (hora del centro de Mexico)').join('; ');
return [{ json: { ok: true, tiene_citas: true, citas, resumen } }];

const raw = $input.first().json || {};
if (raw.body) {
  const expected = $env.N8N_CALENDAR_TOKEN;
  const auth = raw.headers?.authorization || raw.headers?.Authorization || '';
  if (!expected || auth !== `Bearer ${expected}`) throw new Error('AUTH_FAILED: agenda local requiere bearer valido del VPS.');
}
const inp = raw.body || raw;
const crudo = inp.numero_contacto ?? inp.contact_number ?? inp.numero ?? '';
const numero = String(crudo).replace(/[^0-9]/g, '');
if (!numero) throw new Error('FALTA_NUMERO: citas_del_contacto necesita el numero de WhatsApp del contacto.');
return [{ json: { numero } }];
